import { describe, expect, it } from 'vitest';
import pages from './macos-inventory-go-fixture.json';
import { macInventorySections, validMacInventoryPage } from './macos-inventory-types';
// Generated by the synthetic enrollmentstore test, never a native OS provider.
describe('Go store to private TypeScript inventory contract', () => {
 it.each(['summary', ...macInventorySections] as const)('validates the exact Go JSON %s page', section => {
  const page = pages[section];
  expect(validMacInventoryPage(page, page.deviceId, { section, generationId: section === 'summary' ? '' : pages.summary.generationId, offset: 0, limit: 100 })).toBe(true);
 });
 it('keeps the Go summary free of private row values', () => {
  expect(pages.summary.hardware).toBeNull(); expect(pages.summary.receiptIds).toEqual([]); expect(pages.summary.processes).toEqual([]); expect(pages.summary.interfaces).toEqual([]);
 });
});
